import sys, heapq

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    letters = set()
    for w in words:
        letters.update(w)
    adj = {ch: set() for ch in letters}
    indeg = {ch: 0 for ch in letters}
    for a, b in zip(words, words[1:]):
        k = 0
        m = min(len(a), len(b))
        while k < m and a[k] == b[k]:
            k += 1
        if k == m:
            if len(a) > len(b):
                print(-1)
                return
            continue
        if b[k] not in adj[a[k]]:
            adj[a[k]].add(b[k])
            indeg[b[k]] += 1
    heap = [ch for ch in letters if indeg[ch] == 0]
    heapq.heapify(heap)
    out = []
    while heap:
        ch = heapq.heappop(heap)
        out.append(ch)
        for nx in adj[ch]:
            indeg[nx] -= 1
            if indeg[nx] == 0:
                heapq.heappush(heap, nx)
    print(''.join(out) if len(out) == len(letters) else -1)

